def is_majority(arr, n, x):
    def first_occurrence(low, high):
        while low <= high:
            mid = (low + high) // 2
            if (mid == 0 or x > arr[mid - 1]) and arr[mid] == x:
                return mid
            elif x > arr[mid]:
                low = mid + 1
            else:
                high = mid - 1
        return -1

