def magic_square_test(matrix):
    n = len(matrix)
    if n == 0:
        return False
    if any(len(row) != n for row in matrix):
        return False

    target = sum(matrix[0])

    for row in matrix:
        if sum(row) != target:
            return False

    for c in range(n):
        if sum(matrix[r][c] for r in range(n)) != target:
            return False

    if sum(matrix[i][i] for i in range(n)) != target:
        return False

    if sum(matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True
