def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # inc[i]: max sum of increasing subsequence ending at i
    inc = [arr[i] for i in range(n)]
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # dec[i]: max sum of decreasing subsequence starting at i
    dec = [arr[i] for i in range(n)]
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    # combine at peak index i (counted in both inc and dec)
    best = 0
    for i in range(n):
        best = max(best, inc[i] + dec[i] - arr[i])
    return best
```

