def is_majority(arr, n, element):
    if n <= 0:
        return False

    left, right = 0, n
    while left < right:
        mid = (left + right) // 2
        if arr[mid] < element:
            left = mid + 1
        else:
            right = mid

    first = left
    if first == n or arr[first] != element:
        return False

    left, right = first, n
    while left < right:
        mid = (left + right) // 2
        if arr[mid] <= element:
            left = mid + 1
        else:
            right = mid

    return left - first > n / 2
