def magic_square_test(matrix):
    n = len(matrix)
    if n == 0 or any(len(row) != n for row in matrix):
        return False

    values = [value for row in matrix for value in row]
    if len(set(values)) != n * n:
        return False

    target = sum(matrix[0])

    if any(sum(row) != target for row in matrix):
        return False

    if any(sum(matrix[i][j] for i in range(n)) != target for j in range(n)):
        return False

    return (
        sum(matrix[i][i] for i in range(n)) == target
        and sum(matrix[i][n - 1 - i] for i in range(n)) == target
    )
