def is_multiply_prime(a):
    """Return True if a is the product of exactly three prime numbers."""
    if not isinstance(a, int) or a < 2:
        return False

    factors = 0
    divisor = 2

    while divisor * divisor <= a:
        while a % divisor == 0:
            a //= divisor
            factors += 1
            if factors > 3:
                return False
        divisor += 1

    if a > 1:
        factors += 1

