def newman_prime(n):
    """Return the nth Newman–Shanks–Williams prime, using 1-based indexing."""
    if n < 1:
        raise ValueError("n must be a positive integer")

    def is_prime(value):
        if value < 2:
            return False
        if value % 2 == 0:
            return value == 2
        divisor = 3
        while divisor * divisor <= value:
            if value % divisor == 0:
                return False
            divisor += 2
        return True

    # Newman–Shanks–Williams numbers: a(1) = 1, a(2) = 7,
    # a(n) = 6*a(n-1) - a(n-2).
    previous, current = 1, 7
    count = 0

    while True:
        if is_prime(current):
            count += 1
            if count == n:
                return current
        previous, current = current, 6 * current - previous
```

