```python
def next_smallest_palindrome(n: int) -> int:
    s = str(n + 1)

    while True:
        length = len(s)
        half_len = (length + 1) // 2
        left = s[:half_len]

        if length % 2 == 0:
            candidate = left + left[::-1]
        else:
            candidate = left + left[-2::-1]

        if int(candidate) >= int(s):
            return int(candidate)

        left_num = str(int(left) + 1)
        if len(left_num) > half_len:
            s = "1" + "0" * (length - 1) + "1"
        else:
            if length % 2 == 0:
                return int(left_num + left_num[::-1])
            return int(left_num + left_num[-2::-1])
```

