def bell_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")

    bell = [0] * (n + 1)
    bell[0] = 1

    for i in range(1, n + 1):
        total = 0
        for k in range(i):
            total += bell[k] * __import__("math").comb(i - 1, k)
        bell[i] = total

    return bell[n]
```

