def is_multiply_prime(a):
    """Return True if a is the product of exactly three prime numbers."""
    if a < 8:
        return False

    prime_factors = 0
    divisor = 2

    while divisor * divisor <= a:
        while a % divisor == 0:
            prime_factors += 1
            a //= divisor
            if prime_factors > 3:
                return False
        divisor += 1

    if a > 1:
        prime_factors += 1

    return prime_factors == 3
```

