            count += 1
            if count == n:
                return b
        a, b = b, 6 * b - a


def _is_prime(x):
    if x < 2:
        return False
    if x % 2 == 0:
        return x == 2
    limit = math.isqrt(x)
    d = 3
    while d <= limit:
        if x % d == 0:
            return False
        d += 2
    return True
