from functools import cmp_to_key

def find_Max_Num(digits):
    parts = [str(d) for d in digits]

    def compare(a, b):
        if a + b > b + a:
            return -1
        if a + b < b + a:
            return 1
        return 0

    result = ''.join(sorted(parts, key=cmp_to_key(compare)))
    return int(result) if result else 0
```

